    public bool WordBreak(string s, List<string> wordDict) {

        // Raj Thomas 7th May 2026 1:43AM IST
        bool[] dp = new bool[s.Length + 1];
        dp[0] = true; // empty string can be segmented. so true.

        for(int right = 1; right <= s.Length; right++) {

            for(int left = 0; left < right; left++) {
                string subStr = s.Substring(left, right - left);
                if(dp[left] == true && wordDict.Contains(subStr)) {
                    dp[right] = true;
                    break;
                }
            }
        }

        return dp[dp.Length -1];

    }
}
